import { gsap } from 'gsap';
import {
  Group,
  Mesh,
  Box3,
  Vector3,
  SphereGeometry,
  CylinderGeometry,
  PlaneGeometry,
  DoubleSide,
  DirectionalLight,
  PointLight,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, color, mix, smoothstep, vec2, length, atan, positionLocal } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const GroupCtor = Group || THREE.Group;

  const root = new GroupCtor();
  root.name = 'orrery-mechanism';

  const cleanupFns = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // BACKDROP — gradient stage plane
  // ---------------------------------------------------------------
  const stops = (config.intent?.visualSpec?.colors?.gradientStops) ??
    config.colors?.gradientStops ?? [
      { at: 0, hex: '#0b0b10' },
      { at: 0.65, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ];

  const c0 = color(stops[0]?.hex ?? '#0b0b10');
  const c1 = color(stops[1]?.hex ?? '#101017');
  const c2 = color(stops[2]?.hex ?? '#16161d');
  const uvY = uv().y;
  const m1 = smoothstep(0.0, stops[1]?.at ?? 0.65, uvY);
  const m2 = smoothstep(stops[1]?.at ?? 0.65, 1.0, uvY);
  const gradientNode = mix(mix(c0, c1, m1), c2, m2);

  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  backdropMat.colorNode = gradientNode;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  cleanupFns.push(() => { backdropGeo.dispose(); backdropMat.dispose(); });

  // ---------------------------------------------------------------
  // LIGHTS — node-local rim + accent (scene provides ambient 0.6 + key 1.2)
  // ---------------------------------------------------------------
  const rim = new DirectionalLight('#e8ecf2', 0.7);
  rim.position.set(-2.2, 1.4, 3.0);
  root.add(rim);

  const accentPoint = new PointLight('#ff2a38', 0.8, 3, 2);
  accentPoint.position.set(0, 0.1, 1.2);
  root.add(accentPoint);

  // ---------------------------------------------------------------
  // GEAR MECHANISM GROUP
  // ---------------------------------------------------------------
  const mechanism = new GroupCtor();
  mechanism.name = 'mechanism';
  root.add(mechanism);

  const primaryPivot = new GroupCtor();
  primaryPivot.position.set(0, 0, 0);
  mechanism.add(primaryPivot);

  const secondaryPivot = new GroupCtor();
  secondaryPivot.position.set(1.15, 0.35, -0.1);
  mechanism.add(secondaryPivot);

  function createSteelMaterial() {
    const mat = new MeshPhysicalNodeMaterial({
      color: '#8b8d93',
      metalness: 0.55,
      roughness: 0.5,
      clearcoat: 0.2,
      clearcoatRoughness: 0.3,
    });
    mat.anisotropy = 0.7;
    // radial anisotropy so spokes catch light as they turn
    mat.anisotropyRotationNode = atan(positionLocal.y, positionLocal.x);
    return mat;
  }

  const steelMat = createSteelMaterial();
  const ownedMaterials = [steelMat];
  const ownedGeometries = [];

  function fitAndCenter(obj3d, targetDiameter) {
    const box = new Box3().setFromObject(obj3d);
    const size = new Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y, size.z) || 1;
    const scale = targetDiameter / maxDim;
    obj3d.scale.setScalar(scale);

    const box2 = new Box3().setFromObject(obj3d);
    const center = new Vector3();
    box2.getCenter(center);
    obj3d.position.sub(center);
  }

  function applySteel(obj3d) {
    obj3d.traverse((child) => {
      if (child.isMesh) {
        child.material = steelMat;
      }
    });
  }

  let gearLoaded = false;

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!gltf || !gltf.scene) return;

    const primaryScene = gltf.scene;
    fitAndCenter(primaryScene, 1.6);
    applySteel(primaryScene);
    primaryPivot.add(primaryScene);

    const secondaryScene = primaryScene.clone(true);
    // clone shares geometry/material refs — fine, no re-dispose needed for those
    fitAndCenter(secondaryScene, 0.9);
    applySteel(secondaryScene);
    secondaryPivot.add(secondaryScene);

    gearLoaded = true;

    // weighted-settle entrance
    const tl = gsap.timeline();
    mechanism.scale.set(0.001, 0.001, 0.001);
    tl.fromTo(
      mechanism.scale,
      { x: 0.96, y: 0.96, z: 0.96 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
    );
    // start from tiny to visible in one breath (avoid flash)
    mechanism.scale.set(0.96, 0.96, 0.96);
    timelines.push(tl);
  }).catch(() => {
    // fail quiet — stage still reads via backdrop/text
  });

  // meshed rotation via gsap ticker (16:9 ratio -> 0.08 / -0.142 rad/s)
  let lastTick = null;
  const tick = (t) => {
    if (!gearLoaded) { lastTick = t; return; }
    if (lastTick === null) lastTick = t;
    const dt = t - lastTick;
    lastTick = t;
    primaryPivot.rotation.z += 0.08 * dt;
    secondaryPivot.rotation.z -= 0.142 * dt;
  };
  gsap.ticker.add(tick);
  cleanupFns.push(() => gsap.ticker.remove(tick));

  // ---------------------------------------------------------------
  // JEWEL PIVOT — hub accent
  // ---------------------------------------------------------------
  const jewelGeo = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: '#ff2a38',
    transmission: 0.6,
    ior: 1.76,
    thickness: 0.08,
    roughness: 0.08,
    metalness: 0.0,
    emissive: '#ff2a38',
    emissiveIntensity: 1.8,
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.05);
  primaryPivot.add(jewel);
  ownedGeometries.push(jewelGeo);
  ownedMaterials.push(jewelMat);

  // ---------------------------------------------------------------
  // ARBOR SHAFTS — through both hubs
  // ---------------------------------------------------------------
  const shaftGeo = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial({
    color: '#16161d',
    roughness: 0.6,
    metalness: 0.3,
  });
  ownedGeometries.push(shaftGeo);
  ownedMaterials.push(shaftMat);

  const shaftA = new Mesh(shaftGeo, shaftMat);
  shaftA.rotation.x = Math.PI / 2;
  shaftA.position.set(0, 0, 0);
  mechanism.add(shaftA);

  const shaftB = new Mesh(shaftGeo, shaftMat);
  shaftB.rotation.x = Math.PI / 2;
  shaftB.position.set(1.15, 0.35, -0.1);
  mechanism.add(shaftB);

  // ---------------------------------------------------------------
  // CONTACT SHADOW
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(2.6, 1.2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: DoubleSide,
  });
  const suv = uv().sub(vec2(0.5, 0.5));
  const dist = length(suv);
  const falloff = smoothstep(0.5, 0.0, dist);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = falloff.mul(0.5);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -1.2, -1.6);
  root.add(contactShadow);
  ownedGeometries.push(shadowGeo);
  ownedMaterials.push(shadowMat);

  // ---------------------------------------------------------------
  // TEXT
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItem = items.find((i) => i.role === 'caption');

  const headlineText = headlineItem?.text ?? 'The going train';
  const captionText = captionItem?.text ?? '34 COMPONENTS / HAND-FINISHED';

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineItem?.typography?.fontSize ?? 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -0.3,
  });
  headline.position.set(0, -1.7, 0);
  root.add(headline);

  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: captionItem?.typography?.fontSize ?? 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.4,
  });
  caption.position.set(0, -2.1, 0);
  root.add(caption);

  const textTl = gsap.timeline();
  textTl.from(headline.position, { y: '+=0.2', duration: 0.5, ease: 'power2.out' }, 0);
  textTl.from(caption.position, { y: '+=0.2', duration: 0.5, ease: 'power2.out' }, 0.05);
  timelines.push(textTl);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const p of primitiveConfigs) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const handle = fn(root, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) h?.cleanup?.();
    for (const fn of cleanupFns) fn();
    for (const geo of ownedGeometries) geo.dispose();
    for (const mat of ownedMaterials) mat.dispose();
  };

  return root;
}
